SELECT json_build_object(
'succ',(SELECT json_agg(json_build_object('id',s.id,'name',s.name,'n',s."articleCount",'instr',s.preamble_royal_decree,'eff',s.preamble_effective_from::date::text,'preamble',left(s.preamble,700),'classification',s.classification,
  'status',(SELECT verified_status FROM verification v WHERE v.object_type='work' AND v.object_id=s.id ORDER BY v.verified_at DESC, v.id DESC LIMIT 1),
  'work',(SELECT json_agg(json_build_object('work',sm.work_key,'role',sm.role)) FROM search_surface_member sm WHERE sm.system_id=s.id),
  'last',(SELECT json_agg(json_build_object('n',a."articleNumber",'c',left(a.content,500)) ORDER BY a."articleNumber" DESC) FROM (SELECT * FROM legal_articles a2 WHERE a2."legalSystemId"=s.id AND a2."articleBis"<100 ORDER BY a2."articleNumber" DESC LIMIT 2) a),
  'boe',(SELECT json_agg(json_build_object('id',l.id,'name',l.name,'issued',l.issued_hijri,'published',l.published_hijri,'published_g',l.published_gregorian::text,'url',l.url,
      'blocks',(SELECT json_agg(json_build_object('k',b.kind,'b',left(b.body,2500)) ORDER BY b.seq) FROM boe.text_block b WHERE b.law_id=l.id AND b.kind IN ('royal_decree','cabinet_decision')))) FROM boe.law l JOIN boe.current_match m ON m.guid=l.guid WHERE m.hakeem_system_id=s.id),
  'uqn',(SELECT json_agg(json_build_object('src',p.source_id,'url',p.source_url)) FROM (SELECT DISTINCT source_id, source_url FROM legal_text_provenance WHERE entity_id=s.id AND source='uqn' AND entity_type='system') p)) ) FROM legal_systems s WHERE s.id IN ('6e709b849ec7450bb7d9656dc751d44b','cmpz5pb3a001xcwg2gyp5i7lg','cmpz5pd150027cwg25aec1hlf','cmpz5peyx002hcwg2i0z53bv9','cmpz5pf5v002icwg2mt8tagez','cmpz5pqlu0044cwg2dzxmg6u3','cmpz5pqsu0045cwg2qur3vtp4','cmpz5psxm004gcwg2zub1ek0a','cmpz5q64l006bcwg219ge11zr','cmpz5qgt5007tcwg20weum23t','cmpz5qsa7009fcwg2vg2lypd5','cmpz5qz2r00adcwg2tfe62w2s','cmpz5r4i400b5cwg26svw2j78','cmpz5r4p500b6cwg2t04bq0yd','cmpz5rg4c00c2cwg22ehsnc7c','cmpz5rpy400cvcwg2vfc01a54')),
'old',(SELECT json_agg(json_build_object('id',l.id,'blocks',(SELECT json_agg(json_build_object('k',b.kind,'b',left(b.body,2000)) ORDER BY b.seq) FROM boe.text_block b WHERE b.law_id=l.id AND b.kind IN ('royal_decree','cabinet_decision')),
  'last3',(SELECT json_agg(json_build_object('seq',u.seq,'h',u.heading,'b',left(u.body,600)) ORDER BY u.seq) FROM (SELECT * FROM boe.unit u2 WHERE u2.law_id=l.id ORDER BY u2.seq DESC LIMIT 3) u))) FROM boe.law l WHERE l.id IN ('boe26-4695aab79b5d07133858cf8c','boe26-6d5b7a978cf01e426897c877','boe26-b7b6f1348954f58aa8610090','boe26-7611a95fe8dd6dacf15de4d5','boe26-3a463848333bb6b410fabbc9','boe26-65e05bd8c1b2843f92fb7994','boe26-991c74f73b3dcfe1021cccb9','boe26-c04c6c0b7d8bd375a341e3e5','boe26-a7bc10626440105f10c6d08e','boe26-9000690f4bddbd2b25f1d09d','boe26-950044f910153026b5bf31af','boe26-e5c06cbaab583747a8da31e4','boe26-eb3938d9ba353c9db147e801','boe26-fc1e16c803147e8894c4d089','boe26-7a8cdf9c2ebb7e42a9419051','boe26-7d0e1ff55f6b1ea632c1ed75','boe26-e6016f7730dd244be8c6025e','boe26-689d84402e6d3a5cfaca82a5','boe26-62c91ee890ea1e76346332e9','boe26-492c090bd360a722a341962a'))) j